-- Source-verified image correction after Cloudflare rejected an unrelated Houston
-- substation photo and its generic autogenerated replacement for a Panhandle grant.
-- This NASA public-domain 2024 portrait shows the exact named announcer.
-- The existing guarded visual audit must still approve it: NO fabricated pass.
UPDATE public.daily_articles AS d
SET
 image_candidate_url='https://commons.wikimedia.org/wiki/Special:Redirect/file/Greg_Abbott_2024.jpg',
 image_candidate_alt_text='Public-domain NASA archival portrait of Texas Governor Greg Abbott photographed March 26, 2024; not a photograph of the June 2026 Panhandle grant announcement.',
 image_generation_status='pending',
 image_validation_note='Image replacement submitted for guarded visual review: Greg Abbott 2024.jpg, NASA Johnson Space Center / NASA-JSC/Robert Markowitz, public domain as a federal government work; photographed March 26, 2024, during a NASA visit, not the energy grants. Source: https://commons.wikimedia.org/wiki/File:Greg_Abbott_2024.jpg',
 featured_image_url=NULL,
 image_url=NULL,
 image_alt_text=NULL,
 body_json=jsonb_set(
   jsonb_set(d.body_json, '{sections,5,paragraphs,1}', to_jsonb('The original Keep TX Red report at this June 28 address no longer survives as an article record. This page was reconstructed October 14, 2026 from verifiable government information and retains the historical URL with that fact disclosed. The accompanying public-domain NASA portrait shows Governor Greg Abbott during a March 26, 2024 visit to Johnson Space Center in Houston. It is an archival image of the official who announced the grants, not a photograph of the June 2026 grant announcement or North Plains Electric infrastructure.'::text),false),
   '{sources,3}',
   jsonb_build_object('label','Wikimedia Commons — NASA public-domain March 2024 Greg Abbott portrait',
     'url','https://commons.wikimedia.org/wiki/File:Greg_Abbott_2024.jpg'),
   false
 )
WHERE d.slug = 'live-2026-06-28-governor-abbott-announces-more-than-22-million-in-grants-for-electric--tcj84y'
  AND d.image_generation_status IN ('failed','pending')
  AND d.image_candidate_url IS DISTINCT FROM 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Greg_Abbott_2024.jpg'
  AND d.body_json->'sections'->5->'paragraphs'->>1 LIKE '%substation in Houston%'
  AND d.body_json->'sources'->3->>'url' LIKE '%Houston_Lighting%';
